<script setup lang="ts">import{ref}from'vue';import{Head,Link,router}from'@inertiajs/vue3';import{Banknote,Search,Users}from'@lucide/vue';import AppLayout from '@/Layouts/AppLayout.vue';const p=defineProps<{rows:any[],search:string}>();const q=ref(p.search);const load=()=>router.get('/dashboard/saksi',{search:q.value},{preserveState:true,replace:true});</script><template><Head title="Data Saksi"/><AppLayout><main class="mx-auto max-w-7xl space-y-6 p-4"><div><h1 class="text-2xl font-black">Data Saksi</h1><p class="text-sm text-slate-500">Data saksi yang pernah ditambahkan ke dalam berkas pekerjaan.</p></div><section class="overflow-hidden rounded-3xl border bg-white"><header class="flex flex-col justify-between gap-4 border-b p-6 md:flex-row md:items-center"><div class="flex items-center gap-2"><Users class="h-5 w-5 text-pink-500"/><h2 class="font-black">Daftar Saksi & Berkas</h2></div><form @submit.prevent="load" class="relative w-full md:w-72"><Search class="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input v-model="q" class="w-full rounded-xl border-slate-200 pl-9" placeholder="Cari nama saksi..."/></form></header><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4 pl-6">Nama Saksi</th><th>Berkas Yang Ditangani</th><th class="text-center">Status Berkas</th><th class="text-center">Status Invoice</th><th class="pr-6 text-center">Aksi</th></tr></thead><tbody><tr v-if="!rows.length"><td colspan="5" class="py-16 text-center text-slate-400">Belum ada data saksi.</td></tr><tr v-for="x in rows" class="border-t"><td class="p-4 pl-6 font-black">{{x.name}}</td><td><Link :href="`/dashboard/jobs/${x.job.jobType}/${x.job.id}`" class="font-bold text-pink-600">{{x.job.trackingCode}}</Link><p class="text-xs text-slate-500">{{x.job.title}} · {{x.job.clientName}}</p></td><td class="text-center"><span class="rounded-full bg-blue-50 px-3 py-1 text-[10px] font-black text-blue-600">{{x.job.status}}</span></td><td class="text-center"><span class="rounded-full bg-amber-50 px-3 py-1 text-[10px] font-black text-amber-600">{{x.job.invoiceStatus}}</span></td><td class="pr-6 text-center"><button class="inline-flex h-8 items-center gap-1 rounded-lg border border-emerald-200 px-3 text-[10px] font-bold text-emerald-600"><Banknote class="h-3 w-3"/>Tandai Lunas</button></td></tr></tbody></table></section></main></AppLayout></template>
